CREATE OR REPLACE FUNCTION public.trigger_qbo_client_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ BEGIN IF public.is_invoice_cash_payment(NEW) AND NEW.amount > 0 THEN IF TG_OP='UPDATE' THEN IF public.is_invoice_cash_payment(OLD) THEN RETURN NEW; END IF; END IF; INSERT INTO public.agent_notifications(user_id,type,title,message,trip_id,trip_payment_id) VALUES(NEW.user_id,'payment_received','Payment Received','A payment of $' || ROUND(NEW.amount,2)::text || ' has been marked as received.',NEW.trip_id,NEW.id); PERFORM public._post_qbo_sync_trigger('client_payment_received',to_jsonb(NEW),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END); END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS on_trip_payment_paid ON public.trip_payments; CREATE TRIGGER on_trip_payment_paid AFTER INSERT OR UPDATE ON public.trip_payments FOR EACH ROW EXECUTE FUNCTION public.trigger_qbo_client_payment();